=== CritAfterEvade
     1	using System;
     2	using System.Collections;
     3	using UnityEngine;
     4	
     5	public class CritAfterEvade : HeadgearItem
     6	{
     7		public static string staticID = "CritAfterEvade";
     8	
     9		private static GameObject maskPrefab;
    10	
    11		private NumVarStatMod critMod;
    12	
    13		private ChaosQuickStopwatch durationStopwatch = new ChaosQuickStopwatch(3f);
    14	
    15		public CritAfterEvade()
    16		{
    17			ID = staticID;
    18			category = Category.Offense;
    19			if (maskPrefab == null)
    20			{
    21				maskPrefab = ChaosBundle.Get("Assets/Prefabs/Headgear/KitsuneMask.prefab");
    22			}
    23			headgearPrefab = maskPrefab;
    24			critMod = new NumVarStatMod(ID, 1f, 10, VarStatModType.Override);
    25		}
    26	
    27		public override void Activate()
    28		{
    29			base.Activate();
    30			SetEventHandlers(givenStatus: true);
    31		}
    32	
    33		public override void Deactivate()
    34		{
    35			base.Deactivate();
    36			SetEventHandlers(givenStatus: false);
    37		}
    38	
    39		private void SetEventHandlers(bool givenStatus)
    40		{
    41			if (!(parentEntity == null))
    42			{
    43				if (givenStatus)
    44				{
    45					UpdateItemBar(ItemStatusBar.ItemState.Ready);
    46				}
    47				else
    48				{
    49					RemoveFromItemBar();
    50				}
    51				Health health = parentEntity.health;
    52				health.evadeEventHandlers = (Health.EvadeEventHandler)Delegate.Remove(health.evadeEventHandlers, new Health.EvadeEventHandler(OnEvadeEvent));
    53				if (givenStatus)
    54				{
    55					Health health2 = parentEntity.health;
    56					health2.evadeEventHandlers = (Health.EvadeEventHandler)Delegate.Combine(health2.evadeEventHandlers, new Health.EvadeEventHandler(OnEvadeEvent));
    57				}
    58			}
    59		}
    60	
    61		private void OnEvadeEvent()
    62		{
    63			if (durationStopwatch.IsRunning)
    64			{
    65				durationStopwatch.IsRunning = true;
    66			}
    67			else if (parentEntity != null)
    68			{
    69				parentEntity.StartCoroutine(StartCritBuff());
    70			}
    71		}
    72	
    73		private IEnumerator StartCritBuff()
    74		{
    75			if (!durationStopwatch.IsRunning)
    76			{
    77				UpdateItemBar(ItemStatusBar.ItemState.Active);
    78				SetModStatus(givenStatus: true);
    79				durationStopwatch.IsRunning = true;
    80				while (durationStopwatch.IsRunning)
    81				{
    82					yield return null;
    83				}
    84				UpdateItemBar(ItemStatusBar.ItemState.Ready);
    85				SetModStatus(givenStatus: false);
    86			}
    87		}
    88	
    89		private void SetModStatus(bool givenStatus)
    90		{
    91			StatManager.ModifyAllStatData(critMod, parentSkillCategory, "criticalHitChance", IgnoreStatusConditional, givenStatus);
    92		}
    93	}
